<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>چاپ سند {{ $document->document_number }}</title><style>body{font-family:tahoma,sans-serif;font-size:12px}.a4{width:190mm;margin:auto}table{width:100%;border-collapse:collapse}td,th{border:1px solid #999;padding:6px}.sign{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:40px}.sign div{border-top:1px solid #333;text-align:center;padding-top:8px}@media print{button{display:none}}</style></head><body><div class="a4"><button onclick="print()">چاپ</button><h2>سند برگشت از فروش</h2><p>شماره سند: <b>{{ $document->document_number }}</b> | تاریخ: {{ $document->created_at?->format('Y-m-d') }} | مشتری: {{ trim(($document->customer->first_name??'').' '.($document->customer->last_name??'')) }} | فاکتور مرجع: {{ $document->invoice?->uuid ?: $document->external_invoice_number }}</p><p>علت: {{ $document->return_reason }} | توضیحات: {{ $document->description }}</p><table><thead><tr><th>کالا</th><th>تنوع</th><th>تعداد</th><th>انبار مقصد</th><th>مبلغ</th></tr></thead><tbody>@foreach($document->items as $i)<tr><td>{{ $i->product_name_snapshot }}</td><td>{{ $i->variant_name_snapshot }}</td><td>{{ $i->return_quantity }}</td><td>{{ $i->destinationWarehouse?->name }}</td><td>{{ number_format($i->refund_amount) }}</td></tr>@endforeach</tbody></table><h3>جمع بستانکاری: {{ number_format($document->total_refund_amount) }} ریال</h3><div class="sign"><div>ثبت‌کننده</div><div>واحد مالی</div><div>انبار</div><div>مشتری / تحویل‌دهنده</div></div></div></body></html>
